
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_mvsh_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_mvsh", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.664134127454910e+00, -3.590002857846077e+00, -3.486097045253664e+00, -3.342096721342021e+00, -3.145734857490191e+00, -2.884068788301658e+00, -2.546520330960196e+00, -2.130233120887247e+00, -1.646789169061207e+00, -1.127463323164262e+00, -6.108615430895991e-01, -4.668232822899948e-01, -4.818221066925815e-01, -3.991205893862721e-01, -2.719510257406691e-01, -1.457475191685005e-01, -5.016296678859440e-02, -9.713169704826169e-03, -9.591770104639106e-04, -3.632151083445669e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


